insert into private.quiz_answers (challenge_id, idx, accepted, explanation) values
  ('html-check', 0, array['2']::text[], 'HTML stands for Hyper Text Markup Language, the standard markup language for web pages.'),
  ('html-check', 1, array['2']::text[], '<h1> is the largest heading, <h6> the smallest.'),
  ('html-check', 2, array['1']::text[], '<div>, <DIV> and <DiV> all work, but lowercase is the convention.'),
  ('html-check', 3, array['ul']::text[], '<ul> creates a bulleted list; <ol> creates a numbered one.'),
  ('css-check', 0, array['1']::text[], 'display: flex turns the element into a flex container; flex: 1 is for flex items.'),
  ('css-check', 1, array['1']::text[], 'Padding is inside the border; margin is outside.'),
  ('css-check', 2, array['rem']::text[], 'rem = root em. 1rem is the <html> font size.'),
  ('javascript-check', 0, array['1']::text[], 'map returns a new array with the callback applied to every element.'),
  ('javascript-check', 1, array['1']::text[], 'const only prevents reassigning the binding. The object itself can still be mutated.'),
  ('javascript-check', 2, array['1']::text[], '=== is strict equality: no type coercion.'),
  ('a11y-check', 0, array['0']::text[], 'alt="" tells screen readers to skip it. A missing alt makes some readers announce the file name.'),
  ('a11y-check', 1, array['1']::text[], 'A div gets no keyboard focus, no Enter/Space handling and no button role. Use <button>.'),
  ('a11y-check', 2, array['1']::text[], 'AA needs 4.5:1 (3:1 for large text). 7:1 is AAA.'),
  ('tailwind-check', 0, array['0']::text[], 'Breakpoint prefixes go before the utility: md:flex.'),
  ('tailwind-check', 1, array['1']::text[], 'Only classes found in your source files are generated.'),
  ('tailwind-check', 2, array['grid']::text[], 'Most display utilities are named after the value: block, flex, grid. The exception is hidden, which sets display: none.'),
  ('typescript-check', 0, array['3']::text[], 'Array literals infer a union element type, not a tuple. Use `as const` for a tuple.'),
  ('typescript-check', 1, array['1']::text[], 'Types are erased when compiling to JavaScript.'),
  ('typescript-check', 2, array['2']::text[], 'typeof guards narrow primitives. `as` just asserts. It doesn''t check.'),
  ('react-check', 0, array['3']::text[], 'useEffect runs after the render is committed.'),
  ('react-check', 1, array['1']::text[], 'Same array reference means React may skip the re-render. Create a new array: setItems([...items, x]).'),
